-- ============================================================
-- SEED: Módulo 6 — Be Going To (A2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'be-going-to';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo be-going-to não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: am/is/are going to + base verb formation
  (cid,1,1,'gap_fill','She ___ (study) engineering at MIT next fall.','is going to study',NULL,'Be going to: is/am/are + going to + base verb. She → is going to.','easy'),
  (cid,1,2,'gap_fill','We ___ (present) our research at the conference next month.','are going to present',NULL,'We → are going to + base verb.','easy'),
  (cid,1,3,'multiple_choice','Choose the correct form: "I ___ apply for the scholarship."','am going to apply','["is going to apply","am going to apply","are going to apply","going to apply"]','I → am going to + base verb.','easy'),
  (cid,1,4,'gap_fill','They ___ (publish) the findings in a peer-reviewed journal.','are going to publish',NULL,'They → are going to + base verb.','easy'),
  (cid,1,5,'gap_fill','The university ___ (build) a new science center.','is going to build',NULL,'Singular subject → is going to + base verb.','easy'),
  (cid,1,6,'multiple_choice','Which sentence is correct?','He is going to defend his dissertation in June.','["He going to defend his dissertation in June.","He is going to defends his dissertation in June.","He is going to defend his dissertation in June.","He are going to defend his dissertation in June."]','Is going to + base verb (no -s after to).','easy'),
  (cid,1,7,'gap_fill','I ___ (not/miss) another study session this semester.','am not going to miss',NULL,'Negative: am/is/are + not + going to + base verb.','medium'),

  -- BLOCK 2: planned future vs. spontaneous (will)
  (cid,2,8,'multiple_choice','You planned to study abroad before speaking. You say:','I''m going to study in Japan next semester.','["I''ll study in Japan next semester (spontaneous).","I''m going to study in Japan next semester.","I study in Japan next semester.","I was going to study in Japan next semester."]','"Going to" for decisions made before the moment of speaking.','medium'),
  (cid,2,9,'gap_fill','The phone rings and you decide to answer right now: "I ___ (get) it!" (spontaneous)','will get',NULL,'Spontaneous decision = will. Planned decision = going to.','medium'),
  (cid,2,10,'multiple_choice','Which sentence shows a PRE-PLANNED decision?','She has enrolled in a French course — she''s going to start next week.','["Oh, it''s raining — I''ll take an umbrella.","She has enrolled in a French course — she''s going to start next week.","I''ll help you with that equation.","The printer is broken — I''ll fix it."]','"Going to" when the decision was made before speaking (evidence: already enrolled).','medium'),
  (cid,2,11,'gap_fill','A: "The projector isn''t working." B: "Don''t worry, I ___ (fix) it." (spontaneous offer)','will fix',NULL,'Spontaneous offer (decided now) = will.','medium'),
  (cid,2,12,'multiple_choice','You notice a friend has registered for a difficult course. You say:','You''re going to have a lot of work this semester!','["You will have a lot of work this semester (no evidence).","You are going to have a lot of work this semester!","You had a lot of work this semester.","You''re having a lot of work this semester."]','Evidence-based prediction = going to.','hard'),
  (cid,2,13,'gap_fill','He already booked his flight. He ___ (travel) to Oxford to continue his research.','is going to travel',NULL,'Pre-arranged plan with evidence = going to.','medium'),
  (cid,2,14,'multiple_choice','Choose the SPONTANEOUS DECISION:','A: "We need someone to take notes." B: "I''ll do it."','["I''m going to take notes (planned).","A: ''We need someone to take notes.'' B: ''I''ll do it.''","She''s going to take notes — she brought her laptop.","He took notes during the last meeting."]','Will for decisions made at the moment in response to a situation.','medium'),

  -- BLOCK 3: evidence-based predictions
  (cid,3,15,'gap_fill','Look at those storm clouds — it ___ (rain) heavily.','is going to rain',NULL,'"Going to" for predictions based on visible evidence.','medium'),
  (cid,3,16,'multiple_choice','Which sentence uses "going to" for an evidence-based prediction?','He hasn''t studied at all — he''s going to fail the test.','["He will probably fail the test (general opinion).","He is going to fail the test — he hasn''t studied at all.","He failed the test because he didn''t study.","He is failing the test right now."]','Going to = prediction supported by present evidence.','medium'),
  (cid,3,17,'gap_fill','The battery is at 2% — the laptop ___ (die) any minute.','is going to die',NULL,'Evidence visible now → going to for immediate prediction.','medium'),
  (cid,3,18,'multiple_choice','Choose the best prediction based on evidence: "The researchers have collected overwhelming data —"','The findings are going to change our understanding of the disease.','["The findings will change our understanding (general prediction).","The findings are going to change our understanding of the disease.","The findings changed our understanding of the disease.","The findings are changing our understanding now."]','Going to = confident prediction based on existing evidence.','hard'),
  (cid,3,19,'gap_fill','She has been preparing for months — she ___ (do) very well on the TOEFL.','is going to do',NULL,'Evidence (months of preparation) → going to for prediction.','medium'),
  (cid,3,20,'multiple_choice','Identify the evidence-based prediction: "The bridge is showing serious structural damage —"','It''s going to collapse if repairs aren''t made immediately.','["It will collapse someday.","It is collapsing now.","It''s going to collapse if repairs aren''t made immediately.","It has collapsed before."]','Going to + evidence (structural damage already visible) = imminent prediction.','hard'),
  (cid,3,21,'gap_fill','Traffic data shows congestion increasing — commute times ___ (get) much worse.','are going to get',NULL,'Data as evidence → going to for prediction.','hard'),

  -- BLOCK 4: negative form
  (cid,4,22,'gap_fill','She ___ (not/change) her research topic at this stage.','isn''t going to change',NULL,'Negative: is not going to + base verb.','easy'),
  (cid,4,23,'multiple_choice','Which negative sentence is correct?','They aren''t going to accept the proposal without revisions.','["They aren''t going to accepts the proposal.","They aren''t going to accepted the proposal.","They aren''t going to accept the proposal without revisions.","They not going to accept the proposal."]','Are not going to + base verb (no change to verb).','medium'),
  (cid,4,24,'gap_fill','The department ___ (not/fund) the project without a detailed budget plan.','isn''t going to fund',NULL,'Isn''t going to + base verb for negative planned future.','medium'),
  (cid,4,25,'multiple_choice','Choose the correct negative: "I already decided — I ___ retake the exam."','am not going to','["won''t be going to","am not going to","not going to","am going to not"]','"Am not going to" is the correct negative first-person form.','medium'),
  (cid,4,26,'gap_fill','They ___ (not/release) the data until the study is peer-reviewed.','aren''t going to release',NULL,'Aren''t going to + base verb for planned negative future.','medium'),
  (cid,4,27,'multiple_choice','Identify the correct negative response: "Are you going to apply for the grant?" "No, ___."','I''m not going to.','["I''m not going.","I don''t going to.","I''m not going to.","I won''t going to."]','Short negative answer: No, I''m not going to.','medium'),
  (cid,4,28,'gap_fill','He has decided — he ___ (not/pursue) a career in academia.','isn''t going to pursue',NULL,'Negative going to for pre-made decisions.','medium'),

  -- BLOCK 5: questions with going to
  (cid,5,29,'gap_fill','___ (she/give) a presentation at the symposium?','Is she going to give',NULL,'Question: Is/Am/Are + subject + going to + base verb?','easy'),
  (cid,5,30,'multiple_choice','Which question is correct?','Are they going to replicate the study?','["Do they going to replicate the study?","Are they going to replicate the study?","Are they going to replicates the study?","Is they going to replicate the study?"]','Are + they + going to + base verb.','easy'),
  (cid,5,31,'gap_fill','What ___ (the university/do) about the budget cuts?','is the university going to do',NULL,'Wh-question: What + is + subject + going to + base verb?','medium'),
  (cid,5,32,'multiple_choice','Form the correct question: "_____ you apply for the postdoctoral fellowship?"','Are you going to','["Will you going to","Are you going to","Do you going to","Is you going to"]','Are + you + going to + base verb.','easy'),
  (cid,5,33,'gap_fill','Where ___ (they/conduct) the field research?','are they going to conduct',NULL,'Wh-question: Where + are + subject + going to + base verb?','medium'),
  (cid,5,34,'multiple_choice','Choose the correct yes/no answer: "Is she going to submit the application?"','Yes, she is.','["Yes, she is going.","Yes, she does.","Yes, she is.","Yes, she will going to."]','Short answer: Yes, subject + is/am/are.','easy'),
  (cid,5,35,'gap_fill','___ (the committee/announce) the results this week?','Is the committee going to announce',NULL,'Is + subject + going to + base verb? for singular subject.','medium'),

  -- BLOCK 6: going to vs will - contrast exercises
  (cid,6,36,'multiple_choice','Choose the correct form: You have already decided to study abroad next year.','I''m going to study abroad next year.','["I''ll study abroad next year (spontaneous).","I''m going to study abroad next year.","I study abroad next year.","I studied abroad next year."]','Pre-made plan = going to.','medium'),
  (cid,6,37,'gap_fill','A: "There''s no milk." B: "OK, I ___ (get) some from the store." (spontaneous)','will get',NULL,'Spontaneous reaction = will.','medium'),
  (cid,6,38,'multiple_choice','Look at the dark sky — which form is correct?','It''s going to snow — look at those clouds!','["It will snow — look at those clouds!","It''s going to snow — look at those clouds!","It snows — look at those clouds!","It snowed — look at those clouds!"]','Visible evidence → going to for immediate prediction.','medium'),
  (cid,6,39,'gap_fill','She ___ (probably/become) a leading researcher in her field. (general prediction, no specific evidence)','will probably become',NULL,'General opinion-based prediction without specific evidence = will + probably.','hard'),
  (cid,6,40,'multiple_choice','Which sentence uses "going to" correctly for a plan?','He''s going to take a gap year before starting his PhD.','["He''ll take a gap year (spontaneous decision).","He''s going to take a gap year before starting his PhD.","He takes a gap year before starting his PhD.","He took a gap year before starting his PhD."]','Going to for pre-planned decision.','medium'),
  (cid,6,41,'gap_fill','A: "I can''t open this file." B: "Send it to me — I ___ (take) a look." (spontaneous)','will take',NULL,'Spontaneous offer = will.','medium'),
  (cid,6,42,'multiple_choice','Choose: "I''ve already registered and paid the fees — I ___ attend the summer school."','am going to','["will","am going to","am","have"]','Prior commitment with evidence (registered + paid) = going to.','hard'),

  -- BLOCK 7: going to in context - extended practice
  (cid,7,43,'gap_fill','The professor ___ (retire) at the end of this academic year. She has already submitted her notice.','is going to retire',NULL,'Already submitted = prior plan → going to.','medium'),
  (cid,7,44,'multiple_choice','Which sentence about future plans is more natural with "going to"?','We''re going to launch a new interdisciplinary program next fall.','["We''ll launch a new program next fall (spontaneous).","We''re going to launch a new interdisciplinary program next fall.","We launched a new program next fall.","We are launching a new program generally."]','Going to for pre-announced institutional plans.','medium'),
  (cid,7,45,'gap_fill','The data clearly shows a downward trend — the economy ___ (slow) significantly.','is going to slow',NULL,'Data as present evidence → going to for prediction.','hard'),
  (cid,7,46,'multiple_choice','He just tripped — which form is correct?','He''s going to fall!','["He will fall!","He falls!","He''s going to fall!","He fell!"]','Imminent action with visible evidence = going to.','medium'),
  (cid,7,47,'gap_fill','Our team has submitted the proposal. We ___ (hear) back from the committee next month.','are going to hear',NULL,'Expected outcome based on a prior action = going to.','medium'),
  (cid,7,48,'multiple_choice','Choose the sentence that expresses a FIRM PLAN made in advance.','The department is going to restructure its curriculum starting next semester.','["The department will restructure its curriculum (general prediction).","The department is going to restructure its curriculum starting next semester.","The department restructured its curriculum last year.","The department restructures its curriculum every five years."]','Firm institutional plan made in advance = going to.','hard'),
  (cid,7,49,'gap_fill','A: "I heard she applied for the fellowship." B: "Yes, she ___ (start) the program in September."','is going to start',NULL,'Already applied = prior plan → going to.','medium'),

  -- BLOCK 8: mixed going to review
  (cid,8,50,'multiple_choice','Which sentence is grammatically incorrect?','She is going to submits her thesis tomorrow.','["She is going to submit her thesis tomorrow.","I am going to attend the lecture.","They are going to publish the results.","She is going to submits her thesis tomorrow."]','"Going to submits" is wrong — use base verb after "going to".','medium'),
  (cid,8,51,'gap_fill','They ___ (not/present) their work until it has been reviewed by the committee.','aren''t going to present',NULL,'Negative going to for pre-decided conditions.','medium'),
  (cid,8,52,'multiple_choice','Identify the error: "Is he going to presented his findings?"','presented should be present','["Is should be Are","he should be him","going should be goes","presented should be present"]','Going to + base verb (not past tense).','medium'),
  (cid,8,53,'gap_fill','She has already signed the contract. She ___ (join) the research team in January.','is going to join',NULL,'Signed contract = evidence of plan → going to.','medium'),
  (cid,8,54,'multiple_choice','Choose the correct form for an evidence-based prediction.','The patient''s condition is deteriorating — she''s going to need surgery.','["The patient will need surgery (general prediction).","The patient''s condition is deteriorating — she''s going to need surgery.","The patient needed surgery.","The patient needs surgery generally."]','Visible evidence (deteriorating condition) → going to.','hard'),
  (cid,8,55,'gap_fill','The university ___ (invest) in new laboratory equipment following the government grant.','is going to invest',NULL,'Secured grant = evidence of planned investment → going to.','medium'),
  (cid,8,56,'multiple_choice','Which response to "What are your plans after graduation?" best uses going to?','I''m going to pursue a master''s degree in environmental science.','["I''ll pursue a master''s degree.","I pursue a master''s degree.","I''m going to pursue a master''s degree in environmental science.","I pursued a master''s degree."]','Planned post-graduation decision = going to.','easy'),

  -- BLOCK 9: TOEFL academic contexts
  (cid,9,57,'multiple_choice','[TOEFL Listening] The professor says the department has approved a new project. Which form is most appropriate?','The team is going to begin data collection next month.','["The team will begin data collection next month (no prior approval mentioned).","The team is going to begin data collection next month.","The team begins data collection next month.","The team began data collection next month."]','Approved plan = going to.','medium'),
  (cid,9,58,'gap_fill','[TOEFL Reading] According to the article, the government has allocated funds and ___ (expand) its public health infrastructure.','is going to expand',NULL,'Allocated funds = existing evidence of plan → going to.','hard'),
  (cid,9,59,'multiple_choice','[TOEFL Listening] The lecturer shows a graph of rapidly declining fish populations and says:','Fish stocks are going to collapse unless intervention occurs immediately.','["Fish stocks will collapse someday.","Fish stocks are going to collapse unless intervention occurs immediately.","Fish stocks collapsed last year.","Fish stocks collapse every decade."]','Visible data trend = evidence → going to for imminent prediction.','hard'),
  (cid,9,60,'gap_fill','[TOEFL Reading] The passage states that the WHO has already drafted new guidelines and ___ (implement) them by year''s end.','is going to implement',NULL,'Already drafted = prior plan evidence → going to.','hard'),
  (cid,9,61,'multiple_choice','[TOEFL Listening] Which sentence would a professor MOST LIKELY use to describe a planned research initiative?','Our lab is going to collaborate with three universities on this project.','["Our lab will collaborate with three universities (spontaneous).","Our lab is going to collaborate with three universities on this project.","Our lab collaborated with three universities on this project.","Our lab collaborates with three universities."]','Established collaboration plan = going to.','hard'),
  (cid,9,62,'gap_fill','[TOEFL Reading] The company has secured major investors and ___ (launch) a new product line in Q3.','is going to launch',NULL,'Secured investment = concrete plan → going to.','hard'),
  (cid,9,63,'multiple_choice','[TOEFL Listening] The professor points to a graph showing temperature rise and says the Arctic ice ___','is going to disappear within decades if warming continues.','["will disappear within decades (opinion-based).","is going to disappear within decades if warming continues.","disappeared within decades.","disappears within decades."]','Visual evidence (graph) + imminent prediction = going to.','hard'),

  -- BLOCK 10: TOEFL production tasks
  (cid,10,64,'multiple_choice','[TOEFL Reading] Which sentence correctly describes a planned academic initiative with "going to"?','The research team is going to replicate the study using a larger sample size.','["The research team will replicate the study using a larger sample size (general).","The research team is going to replicate the study using a larger sample size.","The research team replicates the study using a larger sample size.","The research team replicated the study using a larger sample size."]','Pre-planned research decision = going to.','hard'),
  (cid,10,65,'gap_fill','[TOEFL Reading] The central bank has announced that it ___ (raise) interest rates next quarter, which analysts predict ___ (slow) economic growth.','is going to raise / will slow',NULL,'Announced plan = going to; general prediction based on it = will.','hard'),
  (cid,10,66,'multiple_choice','[TOEFL Speaking — 45s] You are describing your academic plans. Which response best uses "going to"?','After completing my undergraduate degree, I''m going to apply for a research-based master''s program in neuroscience.','["I will apply for a master''s program someday.","After completing my undergraduate degree, I''m going to apply for a research-based master''s program in neuroscience.","I applied for a master''s program last year.","I am applying for a master''s program right now."]','Personal future plan already decided = going to.','hard'),
  (cid,10,67,'production','[TOEFL Speaking — 45s] Describe your academic or career plans for the next two years. Use "going to" for plans you have already made, and "will" for general predictions about your future. Include at least one evidence-based prediction using "going to".','',NULL,'Going to = pre-planned decisions; will = general predictions.','hard'),
  (cid,10,68,'production','[TOEFL Writing] Write a short paragraph (4-5 sentences) about what a city government is going to do to address a specific urban problem (e.g., traffic, pollution, housing). Use "going to" for planned actions and explain what evidence shows these plans are in place.','',NULL,'Going to for institutional plans; include evidence-based reasoning.','hard'),
  (cid,10,69,'multiple_choice','[TOEFL Writing] Which sentence is most appropriate in an academic report about future policy actions?','The government is going to implement stricter carbon emission standards following the new legislation.','["The government will implement stricter standards (general).","The government is going to implement stricter carbon emission standards following the new legislation.","The government implements stricter standards.","The government implemented stricter standards."]','New legislation = concrete evidence → going to for planned policy.','hard'),
  (cid,10,70,'production','[TOEFL Writing] Write a paragraph comparing two future scenarios: (1) what a university is going to do based on plans already announced, and (2) what will likely happen as a result. Use "going to" for the announced plans and "will" for predicted outcomes.','',NULL,'Distinguish going to (announced plans) from will (resulting predictions).','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
